{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Absolute bioavailability of the 1500 mg GSK1322322 tablet was 57% in fasted healthy volunteers, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "UK-224,671 oral bioavailability was 7.5% in fasted humans with an IV comparator, clearly below the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alizapride absolute oral availability was 72.5% versus IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Higher-weighted positive evidence from multiple absolute human bioavailability measurements supports F >= 20%, despite several transferred molecules with low oral bioavailability values.",
  "evidence_gaps": [
    "Molecule 1 includes a brigatinib record (C22) inconsistent with the GSK1322322 records; it was discounted.",
    "Molecule 7 has conflicting immediate-release bioavailability values (~100% vs 28%); ER absolute values were prioritized.",
    "Molecule 3 is food-dependent (10% fasted, 20% fed); the absolute 9-19% range was used, adding uncertainty.",
    "Molecule 8 orange-juice relative value (C47) was discounted as an altered-condition measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

